require_once 'config.php';require_role('admin');$pageTitle='Post an opportunity';$errors=[];$values=['title'=>'','description'=>'','location'=>'','category'=>'Internship','deadline'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($values as $k=>$v)$values[$k]=trim($_POST[$k]??$v);if(mb_strlen($values['title'])<4)$errors[]='Enter a clear opportunity title.';if(mb_strlen($values['description'])<30)$errors[]='Add a description of at least 30 characters.';if($values['location']==='')$errors[]='Add a location (or enter Remote).';if(!in_array($values['category'],['Internship','Full-time','Part-time','Contract','Freelance','Apprenticeship'],true))$errors[]='Choose a valid category.';if($values['deadline']!=='' && $values['deadline']<date('Y-m-d'))$errors[]='The deadline must be today or in the future.';if(!$errors){$s=$pdo->prepare("INSERT INTO jobs(posted_by,company_name,title,description,location,category,deadline,status) VALUES(?,?,?,?,?,?,?,'published')");$s->execute([current_user()['id'],current_user()['company_name']?:current_user()['name'],$values['title'],$values['description'],$values['location'],$values['category']?:'Internship',$values['deadline']?:null]);flash('success','Your opportunity is live. Thanks for opening a door for someone.');redirect('admin.php');}}
require 'includes/header.php'; ?>
<section class="form-page"><a class="back-link" href="admin.php">← Back to workspace</a><div class="form-page-head"><div class="eyebrow">OPEN A DOOR</div><h1>Post an <span class="text-accent">opportunity.</span></h1><p>Help the right person find their next step. Clear details make all the difference.</p></div><div class="form-card"><div class="form-card-heading"><span class="step-number">01</span><div><h2>Opportunity details</h2><p>Share the essentials candidates need to know.</p></div></div><?php if($errors): ?><div class="alert alert-error" role="alert"><?php foreach($errors as $er): ?><div><?= e($er) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label class="form-field">Job or internship title <span class="required">*</span><input name="title" required maxlength="150" value="<?= e($values['title']) ?>" placeholder="e.g. Frontend Developer Intern"></label><div class="form-row"><label class="form-field">Category <span class="required">*</span><select name="category"><?php foreach(['Internship','Full-time','Part-time','Contract','Freelance','Apprenticeship'] as $cat): ?><option <?= $values['category']===$cat?'selected':'' ?>><?= e($cat) ?></option><?php endforeach; ?></select></label><label class="form-field">Location <span class="required">*</span><input name="location" required value="<?= e($values['location']) ?>" placeholder="e.g. Kochi, Kerala / Remote"></label></div><label class="form-field">Opportunity description <span class="required">*</span><textarea name="description" rows="8" minlength="30" required placeholder="What will the candidate work on? What will they learn? Include responsibilities, skills, and any requirements."><?= e($values['description']) ?></textarea><span class="field-hint">Be specific about the work, expectations, and learning opportunities.</span></label><label class="form-field form-field-short">Application deadline <span class="optional">Optional</span><input type="date" name="deadline" min="<?= date('Y-m-d') ?>" value="<?= e($values['deadline']) ?>"><span class="field-hint">Leave blank if applications are open until the role is filled.</span></label><div class="form-actions"><a class="button button-quiet" href="admin.php">Cancel</a><button class="button button-primary" type="submit">Publish opportunity <span>↗</span></button></div></form></div></section>
